<script setup lang="ts">definePageMeta({middleware:'auth'});const {request}=useApi();const route=useRoute();const router=useRouter();const search=ref(String(route.query.search||''));const page=computed(()=>Number(route.query.page||1));const {data,pending,refresh,error}=await useAsyncData('products',()=>request<{data:any[];meta:any}>(`/products?search=${encodeURIComponent(search.value)}&page=${page.value}`),{watch:[search,page]});watch([search],()=>router.replace({query:{...route.query,search:search.value||undefined,page:1}}));</script><template><section><div class="flex justify-between mb-4"><h1 class="text-2xl font-bold">Products</h1><NuxtLink v-if="false" to="/products/new">Add product</NuxtLink></div><input v-model="search" placeholder="Search product…" class="border p-2 rounded w-full mb-4"><p v-if="pending">Loading…</p><p v-else-if="error">Failed to load products.</p><table v-else class="w-full bg-white"><thead><tr><th>Code</th><th>Name</th><th>Stock</th><th>Price</th></tr></thead><tbody><tr v-for="p in data?.data" :key="p.id"><td>{{p.product_code}}</td><td>{{p.product_name}}</td><td>{{p.stock}}</td><td>Rp {{Number(p.price).toLocaleString('id-ID')}}</td></tr></tbody></table><button class="mt-4" :disabled="page<=1" @click="router.push({query:{...route.query,page:page-1}})">Previous</button><button class="ml-4" @click="router.push({query:{...route.query,page:page+1}})">Next</button></section></template>
